#include <sys/timerfd.h>
#include <time.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <errno.h>

#define handle_error(msg) \ 
    do { perror(msg); exit(EXIT_FAILURE); } while (0)

int main() {
    int tfd;
    struct itimerspec new_value;
    uint64_t expirations;

    // 1. Create a timer file descriptor using the CLOCK_MONOTONIC clock
    tfd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (tfd == -1) {
        handle_error("timerfd_create");
    }

    // 2. Define the timer settings structure
    // Initial expiration: 1 second from now (it_value)
    new_value.it_value.tv_sec = 1;
    new_value.it_value.tv_nsec = 0;
    // Interval: Repeat every 1 second (it_interval)
    new_value.it_interval.tv_sec = 1;
    new_value.it_interval.tv_nsec = 0;

    // 3. Start the periodic timer
    // Flags set to 0 mean relative time, not absolute time (TFD_TIMER_ABSTIME)
    if (timerfd_settime(tfd, 0, &new_value, NULL) == -1) {
        close(tfd);
        handle_error("timerfd_settime");
    }

    printf("Timer set to fire every 1 second. Waiting for 3 ticks...\n");

    // 4. Wait for and process 3 timer expirations
    for (int i = 0; i < 3; i++) {
        ssize_t s = read(tfd, &expirations, sizeof(expirations));

        if (s == -1) {
            if (errno == EINTR) continue; // Retry on interrupt
            close(tfd);
            handle_error("read");
        }

        if (s != sizeof(expirations)) {
            fprintf(stderr, "Error: Short read (%zd bytes)\n", s);
            break;
        }

        // 'expirations' holds the count of missed ticks
        printf("Tick %d: Timer expired (Count: %llu)\n", i + 1, (unsigned long long)expirations);
    }

    close(tfd);
    return EXIT_SUCCESS;
}
